<script setup lang="ts">
import { ref, onMounted, onUnmounted } from 'vue'
import { api, websocketUrl, getToken } from '../lib/api'
const friends=ref<any[]>([]),results=ref<any[]>([])
const search=ref(''),error=ref(''),notice=ref('')
const active=ref<any>(null),messages=ref<any[]>([]),draft=ref(''),showEmoji=ref(false)
const emojis=['😀','😂','🥰','😍','😊','😉','🔥','💪','❤️','👍','🎉','🙏']
const reactionEmojis=['👍','❤️','😂','🔥','👏','😮','😢','💪']
function insertEmoji(emoji:string){draft.value+=emoji;showEmoji.value=false}
async function react(message:any,emoji:string){try{const r=await api<any>(`/messages/${message.id}/reactions`,{method:'POST',body:JSON.stringify({emoji})});message.reactions=r.reactions}catch(e:any){error.value=e.message}}
let socket:WebSocket|null=null
async function load(){friends.value=await api<any[]>('/friends')}
async function find(){error.value='';if(search.value.trim().length<2){results.value=[];return}try{results.value=await api<any[]>(`/users/search?nickname=${encodeURIComponent(search.value.trim())}`)}catch(e:any){error.value=e.message}}
async function request(id:number){try{await api('/friends/requests',{method:'POST',body:JSON.stringify({userId:id})});notice.value='Заявка отправлена';results.value=results.value.filter(x=>x.id!==id)}catch(e:any){error.value=e.message}}
async function openChat(friend:any){closeChat();active.value=friend;try{messages.value=await api<any[]>(`/chats/${friend.id}`);socket=new WebSocket(websocketUrl());socket.onmessage=(ev)=>{const d=JSON.parse(ev.data);if(d.type==='message'&&((d.message.sender_id===friend.id)||(d.message.receiver_id===friend.id))){if(!messages.value.some(m=>m.id===d.message.id))messages.value.push(d.message)}else if(d.type==='reaction'){const target=messages.value.find(m=>m.id===d.messageId);if(target)target.reactions=d.reactions}}}catch(e:any){error.value=e.message}}
function closeChat(){socket?.close();socket=null;active.value=null;messages.value=[]}
function send(){const body=draft.value.trim();if(!body||!active.value||!socket||socket.readyState!==WebSocket.OPEN)return;socket.send(JSON.stringify({receiverId:active.value.id,body}));draft.value=''}
onMounted(async()=>{if(!getToken())return;try{await load()}catch(e:any){error.value=e.message}})
onUnmounted(closeChat)
</script>
<template>
<main class="friends-page">
 <h1>Друзья</h1>
 <div class="friend-tabs"><button class="active">Мои друзья</button><button @click="$router.push('/friends/requests')">Заявки</button></div>
 <p v-if="error" class="friends-message error">{{error}}</p><p v-if="notice" class="friends-message">{{notice}}</p>
 <section v-if="!active" class="friends-search"><label>Найти пользователя по никнейму</label><div class="search-row"><input v-model="search" placeholder="@nickname" @keyup.enter="find"><button @click="find">Найти</button></div>
  <div v-for="user in results" :key="user.id" class="search-result"><div><strong>{{user.name}}</strong><small>@{{user.nickname}}</small></div><button @click="request(user.id)">Добавить</button></div>
 </section>
 <section v-if="!active" class="friends-list"><article v-for="friend in friends" :key="friend.id" class="friend-row"><div class="friend-main"><i class="fa-solid fa-user friend-user-icon"></i><span class="friend-user-name">{{friend.name}} <small>@{{friend.nickname}}</small></span></div><button class="training-button" type="button" @click="openChat(friend)">Пошли тренироваться!</button></article><p v-if="!friends.length" class="empty-state">Пока нет друзей. Найдите пользователя по никнейму.</p></section>
 <section v-if="active" class="chat-panel"><header><button @click="closeChat">← Назад</button><strong>{{active.name}}</strong><small>@{{active.nickname}}</small></header><div class="chat-messages"><div v-for="m in messages" :key="m.id" class="chat-message-wrap" :class="{mine:m.sender_id!==active.id}"><div class="chat-bubble" :class="{mine:m.sender_id!==active.id}">{{m.body}}<small>{{new Date(m.created_at+'Z').toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}}</small></div><div class="message-reactions"><button v-for="r in (m.reactions||[])" :key="r.emoji" :class="{chosen:r.mine}" @click="react(m,r.emoji)">{{r.emoji}} {{r.count}}</button><div class="reaction-picker"><button class="reaction-add" @click="m.showReactions=!m.showReactions">☺</button><div v-if="m.showReactions" class="reaction-options"><button v-for="emoji in reactionEmojis" :key="emoji" @click="react(m,emoji);m.showReactions=false">{{emoji}}</button></div></div></div></div></div><form class="chat-compose" @submit.prevent="send"><div class="compose-emoji"><button type="button" @click="showEmoji=!showEmoji">☺</button><div v-if="showEmoji" class="emoji-picker"><button v-for="emoji in emojis" :key="emoji" type="button" @click="insertEmoji(emoji)">{{emoji}}</button></div></div><input v-model="draft" placeholder="Сообщение…" maxlength="2000"><button type="submit">Отправить</button></form></section>
</main>
</template>
<style scoped>
.friends-page{max-width:480px;margin:0 auto;padding:8px 12px 110px;color:#465675;min-height:calc(100vh - 110px)}.friends-page h1{font-size:42px;line-height:1.1;font-weight:500;letter-spacing:-1.5px;margin:0 0 20px 12px;color:#465675}.friend-tabs{display:flex;gap:8px;margin-bottom:16px}.friend-tabs button{flex:1;padding:11px;border:0;border-radius:9px;background:#e9eef6;color:#657696}.friend-tabs button.active{background:#6798f5;color:white}.friend-tabs span{background:white;color:#6798f5;border-radius:20px;padding:1px 6px}.friends-search{background:white;border-radius:12px;padding:14px;margin-bottom:18px;display:grid;gap:9px;font-size:13px}.search-row{display:flex;gap:8px}.search-row input,.chat-compose input{min-width:0;flex:1;border:1px solid #e0e4ea;border-radius:8px;padding:10px;font:inherit}.search-row button,.search-result button,.request-actions button,.chat-compose button{border:0;border-radius:8px;background:#6798f5;color:white;padding:9px 12px}.search-result,.request-row{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #eef1f5;padding:10px 0}.search-result div,.request-row>div:first-child{display:grid;gap:3px}.search-result small,.request-row small,.friend-user-name small{font-size:11px;color:#8a9bb0}.friends-list{display:grid;gap:12px}.friend-row{background:#fff;border-radius:12px;padding:12px;display:grid;gap:10px}.friend-main{display:flex;align-items:center;gap:12px}.friend-user-icon{font-size:25px;color:#f6c15f}.friend-user-name{font-size:13px;display:grid;gap:3px}.training-button{width:100%;height:36px;border:0;border-radius:7px;background:#f0f2f4;color:#647493;box-shadow:0 2px 2px #3d517033;font-size:12px;letter-spacing:.5px}.request-row{background:#fff;border-radius:12px;padding:14px}.request-actions{display:flex;gap:7px}.request-actions .reject{background:#f0f2f4;color:#657696}.empty-state{color:#8a9bb0;text-align:center;font-size:13px;padding:18px}.friends-message{font-size:12px;color:#4c8b68}.friends-message.error{color:#c65b5b}.chat-message-wrap{display:flex;flex-direction:column;align-items:flex-start;max-width:88%}.chat-message-wrap.mine{align-self:flex-end;align-items:flex-end}.message-reactions{display:flex;gap:4px;flex-wrap:wrap;margin-top:3px}.message-reactions button,.reaction-add{border:1px solid #e2e8f2;border-radius:14px;background:#fff;padding:3px 7px;font-size:12px;cursor:pointer}.message-reactions button.chosen{background:#eaf1ff;border-color:#6798f5}.reaction-picker,.compose-emoji{position:relative}.reaction-options,.emoji-picker{position:absolute;z-index:5;bottom:28px;left:0;background:#fff;border:1px solid #e0e4ea;border-radius:10px;padding:6px;display:flex;flex-wrap:wrap;gap:4px;width:190px;box-shadow:0 5px 18px #24334a22}.emoji-picker{bottom:42px}.compose-emoji>button{width:42px;height:42px;padding:0;font-size:25px;line-height:1}.reaction-options button,.emoji-picker button{border:0;background:#f5f7fb;border-radius:7px;padding:6px;font-size:18px}.chat-panel{background:#fff;border-radius:14px;overflow:hidden;display:flex;flex-direction:column;height:min(65vh,620px)}.chat-panel header{padding:13px;display:flex;align-items:center;gap:9px;border-bottom:1px solid #edf0f4}.chat-panel header button{border:0;background:#eff4ff;color:#547dc4;padding:8px;border-radius:7px}.chat-panel header small{color:#8a9bb0;font-size:11px}.chat-messages{padding:12px;display:flex;flex-direction:column;gap:9px;overflow:auto;flex:1}.chat-bubble{align-self:flex-start;max-width:80%;background:#f0f2f5;border-radius:12px 12px 12px 3px;padding:9px 11px;font-size:13px;white-space:pre-wrap}.chat-bubble.mine{align-self:flex-end;background:#e8f0ff;border-radius:12px 12px 3px 12px}.chat-bubble small{display:block;text-align:right;color:#8a9bb0;font-size:9px;margin-top:4px}.chat-compose{display:flex;align-items:center;gap:7px;padding:10px;border-top:1px solid #edf0f4}
</style>
